from typing import Optionalimport warp as wpfrom . import mathfrom . import constraintfrom . import collision_driverfrom . import passivefrom . import smoothfrom . import solverfrom . import supportfrom .support import xfrc_accumulatefrom .types import Datafrom .types import JointTypefrom .types import Modelfrom .types import TileSetfrom .warp_util import cache_kernelfrom .warp_util import event_scopefrom .warp_util import kernel as nested_kernelwp.set_module_options({"enable_backward": False})@wp.kerneldef _next_position(        # Model:        opt_timestep: float,        jnt_type: wp.array(dtype=int),        jnt_qposadr: wp.array(dtype=int),        jnt_dofadr: wp.array(dtype=int),        jnt_dofnum: wp.array(dtype=int),        # Data in:        qpos_in: wp.array2d(dtype=float),        qvel_in: wp.array2d(dtype=float),        # Data out:        qpos_out: wp.array2d(dtype=float),):    worldid, bodyid = wp.tid()    timestep = opt_timestep    jnttype = jnt_type[bodyid]    qpos_adr = jnt_qposadr[bodyid]    dof_adr = jnt_dofadr[bodyid]    qpos = qpos_in[worldid]    qpos_next = qpos_out[worldid]    qvel = qvel_in[worldid]    if jnttype == JointType.FREE:        qpos_pos = wp.vec3(qpos[qpos_adr], qpos[qpos_adr + 1],                           qpos[qpos_adr + 2])        qvel_lin = wp.vec3(qvel[dof_adr], qvel[dof_adr + 1], qvel[dof_adr + 2])        qpos_new = qpos_pos + timestep * qvel_lin        qpos_quat = wp.quat(            qpos[qpos_adr + 3],            qpos[qpos_adr + 4],            qpos[qpos_adr + 5],            qpos[qpos_adr + 6],        )        qvel_ang = wp.vec3(qvel[dof_adr + 3], qvel[dof_adr + 4],                           qvel[dof_adr + 5])        qpos_quat_new = math.quat_integrate(qpos_quat, qvel_ang, timestep)        qpos_next[qpos_adr + 0] = qpos_new[0]        qpos_next[qpos_adr + 1] = qpos_new[1]        qpos_next[qpos_adr + 2] = qpos_new[2]        qpos_next[qpos_adr + 3] = qpos_quat_new[0]        qpos_next[qpos_adr + 4] = qpos_quat_new[1]        qpos_next[qpos_adr + 5] = qpos_quat_new[2]        qpos_next[qpos_adr + 6] = qpos_quat_new[3]    elif jnttype == JointType.BALL:        qpos_quat = wp.quat(qpos[qpos_adr + 0], qpos[qpos_adr + 1],                            qpos[qpos_adr + 2], qpos[qpos_adr + 3])        qvel_ang = wp.vec3(qvel[dof_adr], qvel[dof_adr + 1], qvel[dof_adr + 2])        qpos_quat_new = math.quat_integrate(qpos_quat, qvel_ang, timestep)        qpos_next[qpos_adr + 0] = qpos_quat_new[0]        qpos_next[qpos_adr + 1] = qpos_quat_new[1]        qpos_next[qpos_adr + 2] = qpos_quat_new[2]        qpos_next[qpos_adr + 3] = qpos_quat_new[3]    elif jnttype == JointType.SLIDE or jnttype == JointType.HINGE:        qpos_next[qpos_adr] = qpos[qpos_adr] + timestep * qvel[dof_adr]    elif jnttype == JointType.UNIVERSAL:        qpos_next[qpos_adr] = qpos[qpos_adr] + timestep * qvel[dof_adr]        qpos_next[qpos_adr + 1] = qpos[qpos_adr + 1] + timestep * qvel[            dof_adr + 1]    elif jnttype == JointType.CUSTOM:        num_dofs = jnt_dofnum[bodyid]        dof_adr = jnt_dofadr[bodyid]        for i in range(num_dofs):            qpos_adr_i = qpos_adr + i            dof_adr_i = dof_adr + i            qpos_next[qpos_adr_i] = qpos[qpos_adr_i] + timestep * qvel[                dof_adr_i]    elif jnttype == JointType.DUMMY:        return    else:        assert False@wp.kerneldef _next_velocity(        # Model:        opt_timestep: float,        # Data in:        qvel_in: wp.array2d(dtype=float),        qacc_in: wp.array2d(dtype=float),        # In:        qacc_scale_in: float,        # Data out:        qvel_out: wp.array2d(dtype=float),):    worldid, dofid = wp.tid()    timestep = opt_timestep    qvel_out[worldid, dofid] = qvel_in[worldid, dofid] + qacc_scale_in * \                               qacc_in[worldid, dofid] * timestep@wp.funcdef _next_act(        # Model:        opt_timestep: float,  # kernel_analyzer: ignore        # Data In:        act_in: float,  # kernel_analyzer: ignore        act_dot_in: float,  # kernel_analyzer: ignore) -> float:    # advance actuation    act = act_in + act_dot_in * opt_timestep    # clamp to actrange    act = wp.clamp(act, 0.0, 1.0)  # blah    return act@wp.kerneldef _next_activation(        # Model:        opt_timestep: wp.array(dtype=float),        # Data in:        act_in: wp.array2d(dtype=float),        act_dot_in: wp.array2d(dtype=float),        # Data out:        act_out: wp.array2d(dtype=float),):    worldid, actid = wp.tid()    opt_timestep_id = worldid % opt_timestep.shape[0]    act = _next_act(        opt_timestep[opt_timestep_id],        act_in[worldid, actid],        act_dot_in[worldid, actid],    )    act_out[worldid, actid] = act@wp.kerneldef _next_time(        # Model:        opt_timestep: float,        # Data in:        time_in: wp.array(dtype=float),        # Data out:        time_out: wp.array(dtype=float),):    worldid = wp.tid()    time_out[worldid] = time_in[worldid] + opt_timestepdef _advance(m: Model, d: Data, qacc: wp.array,             qvel: Optional[wp.array] = None):    """Advance state and time given state derivatives"""    # advance activations    # wp.launch(    #     _next_activation,    #     dim=(d.nworld, m.na),    #     inputs=[    #         m.opt.timestep,    #         d.act,    #         d.act_dot,    #     ],    #     outputs=[d.act],    # )    wp.launch(        _next_velocity,        dim=(d.nworld, m.nv),        inputs=[m.opt.timestep, d.qvel, qacc, 1.0],        outputs=[d.qvel],    )    # advance positions with qvel if given, d.qvel otherwise (semi-implicit)    qvel_in = qvel or d.qvel    wp.launch(        _next_position,        dim=(d.nworld, m.nbody),        inputs=[m.opt.timestep, m.jnt_type, m.jnt_qposadr,                m.jnt_dofadr, m.jnt_dofnum, d.qpos, qvel_in],        outputs=[d.qpos],    )    wp.launch(        _next_time,        dim=d.nworld,        inputs=[m.opt.timestep, d.time],        outputs=[d.time],    )    wp.copy(d.qacc_warmstart, d.qacc)@cache_kerneldef _tile_euler_dense(tile: TileSet):    @nested_kernel(module="unique", enable_backward=False)    def euler_dense(            # Model:            dof_damping: wp.array(dtype=float),            opt_timestep: float,            # Data in:            qM_in: wp.array3d(dtype=float),            efc_Ma_in: wp.array2d(dtype=float),            # In:            adr_in: wp.array(dtype=int),            # Out:            qacc_out: wp.array2d(dtype=float),    ):        worldid, nodeid = wp.tid()        timestep = opt_timestep        TILE_SIZE = wp.static(tile.size)        dofid = adr_in[nodeid]        M_tile = wp.tile_load(qM_in[worldid], shape=(TILE_SIZE, TILE_SIZE),                              offset=(dofid, dofid))        damping_tile = wp.tile_load(dof_damping, shape=(TILE_SIZE,),                                    offset=(dofid,))        damping_scaled = damping_tile * timestep        qm_integration_tile = wp.tile_diag_add(M_tile, damping_scaled)        Ma_tile = wp.tile_load(efc_Ma_in[worldid], shape=(TILE_SIZE,),                               offset=(dofid,))        L_tile = wp.tile_cholesky(qm_integration_tile)        qacc_tile = wp.tile_cholesky_solve(L_tile, Ma_tile)        wp.tile_store(qacc_out[worldid], qacc_tile, offset=(dofid))    return euler_dense@event_scopedef euler(m: Model, d: Data):    """Euler integrator, semi-implicit in velocity."""    # integrate damping implicitly    qacc = wp.empty((d.nworld, m.nv), dtype=float)    for tile in m.qM_tiles:        wp.launch_tiled(            _tile_euler_dense(tile),            dim=(d.nworld, tile.adr.size),            inputs=[m.dof_damping, m.opt.timestep, d.qM, d.efc.Ma, tile.adr],            outputs=[qacc],            block_dim=m.block_dim.euler_dense,        )    _advance(m, d, qacc)@event_scopedef fwd_position(m: Model, d: Data):    """ Position-dependent computations. """    smooth.kinematics(m, d)    smooth.com_pos(m, d)    smooth.muscle_path_length(m, d)    smooth.crb(m, d)    smooth.factor_m(m, d)    collision_driver.collision(m, d)    constraint.make_constraint(m, d)@event_scopedef fwd_velocity(m: Model, d: Data):    """Velocity-dependent computations."""    smooth.com_vel(m, d)    passive.passive(m, d)    smooth.rne(m, d)    smooth.muscle_path_velocity(m, d)@wp.kerneldef _qfrc_actuator(        # Model:        nu: int,        ngravcomp: int,        jnt_actfrclimited: wp.array(dtype=bool),        jnt_actgravcomp: wp.array(dtype=int),        jnt_actfrcrange: wp.array2d(dtype=wp.vec2),        dof_jntid: wp.array(dtype=int),        # Data in:        actuator_moment_in: wp.array3d(dtype=float),        qfrc_gravcomp_in: wp.array2d(dtype=float),        actuator_force_in: wp.array2d(dtype=float),        # Data out:        qfrc_actuator_out: wp.array2d(dtype=float),):    worldid, dofid = wp.tid()    qfrc = float(0.0)    for uid in range(nu):        qfrc += actuator_moment_in[worldid, uid, dofid] * actuator_force_in[            worldid, uid]    jntid = dof_jntid[dofid]    # actuator-level gravity compensation, skip if added as passive force    if ngravcomp and jnt_actgravcomp[jntid]:        qfrc += qfrc_gravcomp_in[worldid, dofid]    if jnt_actfrclimited[jntid]:        frcrange = jnt_actfrcrange[worldid % jnt_actfrcrange.shape[0], jntid]        qfrc = wp.clamp(qfrc, frcrange[0], frcrange[1])    qfrc_actuator_out[worldid, dofid] = qfrc@event_scopedef fwd_actuation(m: Model, d: Data):    """Actuation-dependent computations."""    if m.nmuscle:        # total actuator force at tendon        muscle_actfrc = wp.zeros((d.nworld, m.nmuscle), dtype=float)        # TODO: apply muscle actuation to qfrc    # wp.launch(    #     _qfrc_actuator,    #     dim=(d.nworld, m.nv),    #     inputs=[    #         m.nu,    #         m.ngravcomp,    #         m.jnt_actfrclimited,    #         m.jnt_actgravcomp,    #         m.jnt_actfrcrange,    #         m.dof_jntid,    #         d.actuator_moment,    #         d.qfrc_gravcomp,    #         d.actuator_force,    #     ],    #     outputs=[d.qfrc_actuator],    # )@wp.kerneldef _qfrc_smooth(        # Data in:        qfrc_applied_in: wp.array2d(dtype=float),        qfrc_bias_in: wp.array2d(dtype=float),        qfrc_passive_in: wp.array2d(dtype=float),        # Data out:        qfrc_smooth_out: wp.array2d(dtype=float),):    worldid, dofid = wp.tid()    qfrc_smooth_out[worldid, dofid] = (            qfrc_passive_in[worldid, dofid]            - qfrc_bias_in[worldid, dofid]            + qfrc_applied_in[worldid, dofid]    )@event_scopedef fwd_acceleration(m: Model, d: Data, factorize: bool = False):    """Add up all non-constraint forces, compute qacc_smooth.    Args:      m: The model containing kinematic and dynamic information.      d: The data object containing the current state and output arrays.      factorize: Flag to factorize inertia matrix.    """    wp.launch(        _qfrc_smooth,        dim=(d.nworld, m.nv),        inputs=[d.qfrc_applied, d.qfrc_bias, d.qfrc_passive],        outputs=[d.qfrc_smooth],    )    xfrc_accumulate(m, d, d.qfrc_smooth)    if factorize:        smooth.factor_solve_i(m, d, d.qM, d.qLD, d.qacc_smooth, d.qfrc_smooth)    else:        smooth.solve_m(m, d, d.qacc_smooth, d.qfrc_smooth)@event_scopedef forward(m: Model, d: Data):    """Forward dynamics."""    fwd_position(m, d)    fwd_velocity(m, d)    fwd_actuation(m, d)    fwd_acceleration(m, d, factorize=True)    solver.solve(m, d)@event_scopedef step(m: Model, d: Data):    """Advance simulation."""    forward(m, d)    euler(m, d)